// 方案一（推荐）：枚举单例 —— 天然防反射/反序列化破坏，且线程安全
public enum Singleton {
    INSTANCE;
    public void doWork() { /* ... */ }
}

// 方案二：静态内部类（懒加载 + 类加载机制保证线程安全）
public class Singleton {
    private Singleton() {}
    private static class Holder { static final Singleton INSTANCE = new Singleton(); }
    public static Singleton getInstance() { return Holder.INSTANCE; }
}

// 方案三：双重检查锁（注意 volatile 禁止指令重排序）
public class Singleton {
    private static volatile Singleton instance;
    private Singleton() {}
    public static Singleton getInstance() {
        if (instance == null) {
            synchronized (Singleton.class) {
                if (instance == null) instance = new Singleton();
            }
        }
        return instance;
    }
}

class LruCache<K, V> extends LinkedHashMap<K, V> {
    private final int cap;
    LruCache(int cap) {
        super(cap, 0.75f, true);   // accessOrder=true：按访问顺序排序
        this.cap = cap;
    }
    @Override protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {
        return size() > cap;
    }
    @Override public synchronized V get(Object key) { return super.get(key); }
    @Override public synchronized V put(K key, V value) { return super.put(key, value); }
}

class Node {
    int val; Node next;
    Node(int v) { val = v; }
}
static Node reverse(Node head) {
    Node prev = null, cur = head;
    while (cur != null) {
        Node nxt = cur.next;   // 先保存后继
        cur.next = prev;       // 反转指针
        prev = cur;            // prev 前移
        cur = nxt;             // cur 前移
    }
    return prev;               // 新头结点
}

class Buffer {
    private String item;
    public synchronized void put(String s) throws InterruptedException {
        while (item != null) wait();     // 满则等待，被唤醒后必须重新检查
        item = s;
        notifyAll();
    }
    public synchronized String take() throws InterruptedException {
        while (item == null) wait();     // 空则等待
        String s = item;
        item = null;
        notifyAll();
        return s;
    }
}

public final class ImmutablePoint {
    private final int x;
    private final int y;
    public ImmutablePoint(int x, int y) { this.x = x; this.y = y; }
    public int getX() { return x; }
    public int getY() { return y; }
    @Override public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof ImmutablePoint p)) return false;
        return x == p.x && y == p.y;
    }
    @Override public int hashCode() { return Objects.hash(x, y); }
    @Override public String toString() { return "(" + x + ", " + y + ")"; }
}

static boolean valid(String s) {
    Deque<Character> st = new ArrayDeque<>();
    for (char c : s.toCharArray()) {
        if (c == '(' || c == '[' || c == '{') st.push(c);
        else {
            if (st.isEmpty()) return false;
            char o = st.pop();
            if ((c == ')' && o != '(') || (c == ']' && o != '[')
                || (c == '}' && o != '{')) return false;
        }
    }
    return st.isEmpty();
}

ThreadPoolExecutor pool = new ThreadPoolExecutor(
        4, 8, 30, TimeUnit.SECONDS,
        new ArrayBlockingQueue<>(100),
        Executors.defaultThreadFactory(),
        new ThreadPoolExecutor.CallerRunsPolicy());

List<Future<Integer>> fs = new ArrayList<>();
for (int i = 0; i < 10; i++) {
    final int n = i;
    fs.add(pool.submit(() -> n * n));
}
int sum = 0;
for (Future<Integer> f : fs) {
    try { sum += f.get(5, TimeUnit.SECONDS); }   // 带超时，抛 ExecutionException 时保留 cause
    catch (Exception e) { e.printStackTrace(); }
}
pool.shutdown();
try { if (!pool.awaitTermination(10, TimeUnit.SECONDS)) pool.shutdownNow(); }
catch (InterruptedException e) { Thread.currentThread().interrupt(); }
